BEGIN;
SET LOCAL ROLE celebix_saas_owner;
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE order_bump_checks(name text PRIMARY KEY);
CREATE FUNCTION pg_temp.order_bump_fail_receipt() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF current_setting('celebix.order_bump.inject_failure',true)='1' THEN RAISE EXCEPTION 'ORDER_BUMP223_INJECTED_FAILURE';END IF;RETURN NEW;END $f$;
DO $test$
DECLARE
 st uuid:='a2230000-0000-4000-8000-000000000001';otherst uuid:='a2230000-0000-4000-8000-000000000011';pr uuid:='a2230000-0000-4000-8000-000000000002';mb uuid:='a2230000-0000-4000-8000-000000000003';othermb uuid:='a2230000-0000-4000-8000-000000000013';pl uuid:='a2230000-0000-4000-8000-000000000004';cash uuid:='a2230000-0000-4000-8000-000000000005';cashmb uuid:='a2230000-0000-4000-8000-000000000006';
 p1 uuid:='a2230000-0000-4000-8000-000000000020';p2 uuid:='a2230000-0000-4000-8000-000000000021';p3 uuid:='a2230000-0000-4000-8000-000000000022';foreignp uuid:='a2230000-0000-4000-8000-000000000023';v1 uuid:='a2230000-0000-4000-8000-000000000030';v2 uuid:='a2230000-0000-4000-8000-000000000031';v3 uuid:='a2230000-0000-4000-8000-000000000032';v4 uuid:='a2230000-0000-4000-8000-000000000033';foreignv uuid:='a2230000-0000-4000-8000-000000000034';c1 uuid:='a2230000-0000-4000-8000-000000000040';c2 uuid:='a2230000-0000-4000-8000-000000000041';cart uuid:='a2230000-0000-4000-8000-000000000050';ruleid uuid:='a2230000-0000-4000-8000-000000000060';
 n timestamptz:=date_trunc('milliseconds',transaction_timestamp())-interval '1 hour';config jsonb;empty_config jsonb;rule jsonb;creds jsonb:=jsonb_build_array(jsonb_build_object('keyId','qa223','digest',repeat('a',64)));r record;receipt jsonb;canonical jsonb;realcart uuid:='a2230000-0000-4000-8000-000000000051';loc uuid;sale uuid:='a2230000-0000-4000-8000-000000000070';intent jsonb;op uuid:=gen_random_uuid();
BEGIN
 INSERT INTO saas.stores(id,name,slug,status,locale,currency,theme_key,created_at,updated_at) VALUES(st,'Order bump fixture','order-bump-223','active','tr','TRY','hemenaku',n,n),(otherst,'Foreign fixture','order-bump-other-223','active','tr','TRY','hemenaku',n,n);
