 INSERT INTO saas.memberships VALUES(mb,pr,st,'store_owner','active',n,n),(othermb,pr,otherst,'store_owner','active',n,n),(cashmb,cash,st,'cashier','active',n,n);
 INSERT INTO saas.plans VALUES(pl,'bump223_qa',1,'active',n-interval '1 day',NULL,n,n);ALTER TABLE saas.plan_features DISABLE TRIGGER plan_features_immutable;INSERT INTO saas.plan_features VALUES(pl,'catalog',1,true),(pl,'orders',2,true);ALTER TABLE saas.plan_features ENABLE TRIGGER plan_features_immutable;
 INSERT INTO saas.subscriptions VALUES(gen_random_uuid(),st,pl,'bump223_qa',1,'active',n-interval '1 day',NULL,n,n),(gen_random_uuid(),otherst,pl,'bump223_qa',1,'active',n-interval '1 day',NULL,n,n);
 INSERT INTO saas.store_domains(id,store_id,hostname,hostname_type,status,is_primary,verified_at,created_at,updated_at) VALUES(gen_random_uuid(),st,'order-bump-223.qa.celebix.invalid','platform_subdomain','active',true,n,n,n),(gen_random_uuid(),otherst,'order-bump-other-223.qa.celebix.invalid','platform_subdomain','active',true,n,n,n);
 INSERT INTO saas.domains(id,store_id,normalized_hostname,domain_type,status,canonical,cache_version,created_at,updated_at) VALUES(gen_random_uuid(),st,'order-bump-223.qa.celebix.invalid','platform_subdomain','active',true,1,n,n);
 INSERT INTO saas.products(id,store_id,slug,title,status,currency,created_at,updated_at) VALUES(p1,st,'source-shoe','Ayakkabı','active','TRY',n,n),(p2,st,'target-sock','Çorap','active','TRY',n,n),(p3,st,'target-care','Bakım','active','TRY',n,n),(foreignp,otherst,'foreign-product','Başka mağaza','active','TRY',n,n);
