 INSERT INTO saas.catalog_categories(id,store_id,name,slug,created_at,updated_at) VALUES(c1,st,'Birinci kategori','first-category',n,n),(c2,st,'İkinci kategori','second-category',n,n);INSERT INTO saas.catalog_product_categories(store_id,product_id,category_id,position) VALUES(st,p1,c1,0),(st,p1,c2,1);
 INSERT INTO saas.storefront_carts VALUES(cart,st,'active',1,n+interval '1 day',n,n);INSERT INTO saas.storefront_cart_credentials VALUES(cart,st,'qa223',repeat('a',64),n+interval '1 day');INSERT INTO saas.storefront_cart_items(cart_id,store_id,product_id,variant_id,quantity,unit_price_cents,position,created_at,updated_at) VALUES(cart,st,p1,v1,1,10000,0,n,n);
 SELECT * INTO r FROM saas.order_bump_settings_get(st,pr,mb,pl,'bump223_qa',1,n);IF r.outcome<>'ok' OR r.result_payload->>'version'<>'0' OR r.result_payload->'updatedAt'<>'null'::jsonb OR(r.result_payload->'config'->>'enabled')::boolean THEN RAISE EXCEPTION 'BUMP223_DEFAULT:%',r;END IF;empty_config:=r.result_payload->'config';INSERT INTO order_bump_checks VALUES('new stores default disabled without writing records');
 rule:=jsonb_build_object('id',ruleid,'name','Ayakkabıya çorap','enabled',true,'productIds',jsonb_build_array(p1),'categoryIds',jsonb_build_array(c2),'minSubtotalCents',10000,'maxSubtotalCents',20000,'variantIds',jsonb_build_array(v2,v3,v4));config:=empty_config||jsonb_build_object('enabled',true,'rules',jsonb_build_array(rule));
 SELECT * INTO r FROM saas.order_bump_settings_save(st,cash,cashmb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('1',64),0,config);IF r.outcome NOT IN('role_denied','membership_denied') THEN RAISE EXCEPTION 'BUMP223_CASHIER:%',r.outcome;END IF;INSERT INTO order_bump_checks VALUES('cashier configuration writes denied');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('1',64),0,jsonb_set(config,'{maxOffers}','4'));IF r.outcome<>'invalid_input' OR EXISTS(SELECT 1 FROM saas.order_bump_operations WHERE store_id=st) THEN RAISE EXCEPTION 'BUMP223_INVALID_JSON';END IF;INSERT INTO order_bump_checks VALUES('native rejects malformed config before writing');
 SELECT * INTO r FROM saas.order_bump_options(st,pr,mb,pl,'bump223_qa',1,n,'variant',10001,NULL,NULL,NULL);IF r.outcome<>'invalid_input' THEN RAISE EXCEPTION 'BUMP223_NATIVE_PAGE';END IF;
 SELECT * INTO r FROM saas.order_bump_options(st,pr,mb,pl,'bump223_qa',1,n,'variant',1,'x',NULL,ARRAY[v2]);IF r.outcome<>'invalid_input' THEN RAISE EXCEPTION 'BUMP223_NATIVE_MODE';END IF;INSERT INTO order_bump_checks VALUES('native options reject unbounded pages and mixed selector modes');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('1',64),0,jsonb_set(config,'{rules,0,variantIds}',jsonb_build_array(foreignv)));IF r.outcome<>'invalid_reference' THEN RAISE EXCEPTION 'BUMP223_FOREIGN:%',r.outcome;END IF;INSERT INTO order_bump_checks VALUES('foreign references rejected');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,op,repeat('2',64),0,config);IF r.outcome<>'saved' OR r.result_payload->>'version'<>'1' THEN RAISE EXCEPTION 'BUMP223_SAVE:%',r.outcome;END IF;receipt:=r.result_payload;INSERT INTO order_bump_checks VALUES('save records real actor membership and version atomically');
 IF NOT EXISTS(SELECT 1 FROM saas.order_bump_operations WHERE store_id=st AND operation_id=op AND principal_id=pr AND membership_id=mb) THEN RAISE EXCEPTION 'BUMP223_AUDIT';END IF;
 UPDATE saas.memberships SET role='store_owner' WHERE id=cashmb;UPDATE saas.memberships SET role='cashier' WHERE id=mb;SELECT * INTO r FROM saas.order_bump_operation_get(st,pr,mb,pl,'bump223_qa',1,n,op,repeat('2',64));IF r.outcome NOT IN('membership_denied','role_denied') OR r.result_payload IS NOT NULL THEN RAISE EXCEPTION 'BUMP223_REVOKED_REPLAY';END IF;UPDATE saas.memberships SET role='store_owner' WHERE id=mb;UPDATE saas.memberships SET role='cashier' WHERE id=cashmb;INSERT INTO order_bump_checks VALUES('replay rechecks current permission before returning evidence');
 BEGIN UPDATE saas.order_bump_operations SET result_payload='{}' WHERE store_id=st AND operation_id=op;RAISE EXCEPTION 'BUMP223_MUTABLE_RECEIPT';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'MERCHANT_ADMIN_IMMUTABLE' THEN RAISE;END IF;END;INSERT INTO order_bump_checks VALUES('operation journal cannot be edited or deleted');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,op,repeat('2',64),0,config);IF r.outcome<>'replayed' OR r.result_payload<>receipt THEN RAISE EXCEPTION 'BUMP223_REPLAY';END IF;INSERT INTO order_bump_checks VALUES('same operation returns original frozen result');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,op,repeat('2',64),0,jsonb_set(config,'{enabled}','false'));IF r.outcome<>'operation_mismatch' THEN RAISE EXCEPTION 'BUMP223_PAYLOAD';END IF;INSERT INTO order_bump_checks VALUES('same operation different payload rejected');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('2',64),0,config);IF r.outcome<>'version_conflict' THEN RAISE EXCEPTION 'BUMP223_CAS';END IF;INSERT INTO order_bump_checks VALUES('stale settings cannot overwrite');
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF r.outcome<>'ok' OR r.result_payload->>'cartVersion'<>'1' OR jsonb_array_length(r.result_payload->'offers')<>1 OR r.result_payload->'offers'->0->>'variantId'<>v2::text OR r.result_payload->'offers'->0->>'priceCents'<>'2500' THEN RAISE EXCEPTION 'BUMP223_PUBLIC:%',r;END IF;INSERT INTO order_bump_checks VALUES('secondary category and inclusive subtotal match exact selected variant price');INSERT INTO order_bump_checks VALUES('same product deduplicated and unavailable variant omitted');
 -- Real current cart API, including abandoned-cart hooks, must leave the last selected unit available to its own cart.
 UPDATE saas.product_variants SET stock_quantity=1 WHERE id=v1;
 SELECT * INTO r FROM saas.public_cart_mutate('order-bump-223.qa.celebix.invalid',n,'[]',realcart,'qa223real',repeat('b',64),n+interval '1 day',gen_random_uuid(),repeat('a',64),'add',0,p1,v1,1,'[]');
 IF r.outcome<>'committed' THEN RAISE EXCEPTION 'BUMP223_REAL_CART:%',r;END IF;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,jsonb_build_array(jsonb_build_object('keyId','qa223real','digest',repeat('b',64))),'side_cart');
 IF jsonb_array_length(r.result_payload->'offers')<>1 OR r.result_payload->'offers'->0->>'variantId'<>v2::text THEN RAISE EXCEPTION 'BUMP223_LAST_UNIT:%',r;END IF;UPDATE saas.product_variants SET stock_quantity=10 WHERE id=v1;
 INSERT INTO order_bump_checks VALUES('real cart API last unit still receives recommendations');
 canonical:=saas.public_effective_product_projection(st,p2,n);SELECT value INTO canonical FROM jsonb_array_elements(canonical->'variants') WHERE value->>'id'=v2::text;
 IF r.result_payload->'offers'->0->>'priceCents' IS DISTINCT FROM canonical->>'priceCents' OR r.result_payload->'offers'->0->>'variantTitle' IS DISTINCT FROM canonical->>'title' THEN RAISE EXCEPTION 'BUMP223_CANONICAL_VARIANT';END IF;INSERT INTO order_bump_checks VALUES('exact selected variant matches canonical public product price and title');
 -- Product exclusion and matching groups/bounds are evaluated independently of editor state.
 UPDATE saas.order_bump_settings SET config=jsonb_set(receipt->'config','{rules,0,variantIds}',jsonb_build_array(v1,v2)) WHERE store_id=st;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF jsonb_array_length(r.result_payload->'offers')<>1 OR r.result_payload->'offers'->0->>'productId'<>p2::text THEN RAISE EXCEPTION 'BUMP223_IN_CART';END IF;INSERT INTO order_bump_checks VALUES('entire already selected product excluded');
 UPDATE saas.order_bump_settings SET config=jsonb_set(receipt->'config','{rules,0,productIds}',jsonb_build_array(p2)) WHERE store_id=st;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF r.result_payload->'offers'<>'[]'::jsonb OR r.result_payload->>'heading' IS DISTINCT FROM 'Bunları da beğenebilirsiniz' THEN RAISE EXCEPTION 'BUMP223_ENABLED_EMPTY:%',r;END IF;INSERT INTO order_bump_checks VALUES('enabled no match remains distinct from disabled fallback');
 UPDATE saas.order_bump_settings SET config=jsonb_set(receipt->'config','{rules,0,categoryIds}',jsonb_build_array(c1)) WHERE store_id=st;DELETE FROM saas.catalog_product_categories WHERE store_id=st AND product_id=p1 AND category_id=c1;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'BUMP223_CATEGORY_AND';END IF;INSERT INTO saas.catalog_product_categories(store_id,product_id,category_id,position) VALUES(st,p1,c1,0);
 UPDATE saas.order_bump_settings SET config=jsonb_set(receipt->'config','{rules,0,minSubtotalCents}','10001') WHERE store_id=st;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'BUMP223_LOWER_BOUND';END IF;
 UPDATE saas.order_bump_settings SET config=jsonb_set(jsonb_set(receipt->'config','{rules,0,minSubtotalCents}','null'),'{rules,0,maxSubtotalCents}','9999') WHERE store_id=st;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'BUMP223_UPPER_BOUND';END IF;
 UPDATE saas.order_bump_settings SET config=receipt->'config' WHERE store_id=st;
 INSERT INTO order_bump_checks VALUES('all nonempty trigger groups and subtotal bounds must match');
 SELECT id INTO loc FROM saas.inventory_locations WHERE store_id=st AND is_default;
 intent:=jsonb_build_object('locationId',loc,'items',jsonb_build_array(jsonb_build_object('variantId',v2,'quantity',10),jsonb_build_object('variantId',v3,'quantity',10)),'discount',NULL,'customerName',NULL,'note',NULL);
 SELECT * INTO r FROM saas.in_store_sales_create(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('b',64),sale,intent);IF r.outcome<>'committed' THEN RAISE EXCEPTION 'BUMP223_HOLD_CREATE:%',r;END IF;
 SELECT * INTO r FROM saas.in_store_sales_prepare(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('c',64),sale,1,51000);IF r.outcome<>'committed' OR saas.storefront_available_stock(st,v2,n,NULL)<>0 OR saas.storefront_available_stock(st,v3,n,NULL)<>0 THEN RAISE EXCEPTION 'BUMP223_HOLD_PREPARE:%',r;END IF;
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'checkout');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'BUMP223_HELD_STOCK';END IF;
 SELECT * INTO r FROM saas.in_store_sales_cancel(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('d',64),sale,2,true);IF r.outcome<>'committed' THEN RAISE EXCEPTION 'BUMP223_HOLD_RELEASE:%',r;END IF;INSERT INTO order_bump_checks VALUES('real prepared sale reservations remove offers without reducing physical stock');
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-other-223.qa.celebix.invalid',n,creds,'checkout');IF r.result_payload->'offers'<>'[]'::jsonb OR r.result_payload->'cartVersion'<>'null'::jsonb THEN RAISE EXCEPTION 'BUMP223_PUBLIC_TENANT';END IF;INSERT INTO order_bump_checks VALUES('public credentials cannot cross store boundary');
 SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,'[]','checkout');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'BUMP223_EMPTY';END IF;INSERT INTO order_bump_checks VALUES('missing cart is empty optional read');
 UPDATE saas.product_variants SET price_cents=11000 WHERE id=v1;SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'checkout');IF r.result_payload->'offers'<>'[]'::jsonb OR(SELECT unit_price_cents FROM saas.storefront_cart_items WHERE cart_id=cart)<>10000 THEN RAISE EXCEPTION 'BUMP223_DRIFT';END IF;UPDATE saas.product_variants SET price_cents=10000 WHERE id=v1;INSERT INTO order_bump_checks VALUES('price drift suppresses offers without modifying cart');
 UPDATE saas.product_variants SET status='archived',archived_at=n WHERE id=v2;UPDATE saas.product_variants SET status='archived',archived_at=n WHERE id=v3;SELECT * INTO r FROM saas.order_bump_public_offers('order-bump-223.qa.celebix.invalid',n,creds,'side_cart');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'BUMP223_ARCHIVE';END IF;INSERT INTO order_bump_checks VALUES('archived variants cannot become public offers');
 SELECT * INTO r FROM saas.order_bump_options(st,pr,mb,pl,'bump223_qa',1,n,'variant',1,NULL,NULL,ARRAY[v2,foreignv]);IF jsonb_array_length(r.result_payload->'items')<>1 OR r.result_payload->'items'->0->>'id'<>v2::text OR(r.result_payload->'items'->0->>'available')::boolean THEN RAISE EXCEPTION 'BUMP223_OPTIONS:%',r;END IF;INSERT INTO order_bump_checks VALUES('selected unavailable labels retained without foreign resources');
 SELECT * INTO r FROM saas.order_bump_settings_save(st,pr,mb,pl,'bump223_qa',1,n,gen_random_uuid(),repeat('3',64),1,empty_config);IF r.outcome<>'saved' OR r.result_payload->>'version'<>'2' THEN RAISE EXCEPTION 'BUMP223_REMOVE';END IF;INSERT INTO order_bump_checks VALUES('rule removal and disable advance version without deleting evidence');
 SELECT * INTO r FROM saas.order_bump_operation_get(st,pr,mb,pl,'bump223_qa',1,n,op,repeat('2',64));IF r.outcome<>'replayed' OR r.result_payload<>receipt THEN RAISE EXCEPTION 'BUMP223_RECOVERY';END IF;INSERT INTO order_bump_checks VALUES('recovery keeps original result after newer settings');
END $test$;
CREATE TRIGGER order_bump_atomic_fixture BEFORE INSERT ON saas.order_bump_operations FOR EACH ROW EXECUTE FUNCTION pg_temp.order_bump_fail_receipt();
DO $atomic$ DECLARE r record;op uuid:=gen_random_uuid();BEGIN
 PERFORM set_config('celebix.order_bump.inject_failure','1',true);BEGIN
  PERFORM * FROM saas.order_bump_settings_save('a2230000-0000-4000-8000-000000000001','a2230000-0000-4000-8000-000000000002','a2230000-0000-4000-8000-000000000003','a2230000-0000-4000-8000-000000000004','bump223_qa',1,date_trunc('milliseconds',transaction_timestamp()),op,repeat('4',64),2,saas.order_bump_default_config());RAISE EXCEPTION 'BUMP223_EXPECTED_FAILURE';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'ORDER_BUMP223_INJECTED_FAILURE' THEN RAISE;END IF;END;
 IF(SELECT version FROM saas.order_bump_settings WHERE store_id='a2230000-0000-4000-8000-000000000001')<>2 OR EXISTS(SELECT 1 FROM saas.order_bump_operations WHERE operation_id=op) THEN RAISE EXCEPTION 'BUMP223_NOT_ATOMIC';END IF;INSERT INTO order_bump_checks VALUES('receipt failure rolls back settings and journal');
END $atomic$;
DROP TRIGGER order_bump_atomic_fixture ON saas.order_bump_operations;DROP FUNCTION pg_temp.order_bump_fail_receipt();
SELECT name FROM order_bump_checks ORDER BY name;
ROLLBACK;
